def scen_summary(r):
    if not r: return 'not run'
    s = r['scen']; ok = sum(1 for v in s.values() if v.get('diffs') == [])
    by = sum(v.get('bytesCompared') or 0 for v in s.values())
    other = [k.split(' ')[0] for k, v in s.items() if v.get('diffs') != []]
    return '%d of %d scenarios identical (%d bytes compared)%s' % (ok, len(s), by, (', not identical: ' + ', '.join(other)) if other else '')
def borrow_summary(r):
    if not r: return 'not run'
    b = r['borrow']; return '%d of %d equal' % (sum(1 for v in b.values() if v.get('equal')), len(b))

